{"command": "@'
const fs = require("fs");
const path = require("path");
const compiler = require("vue-template-compiler");

function loadMod(p) {
  const src = fs.readFileSync(p, "utf8").replace(/export default/, "module.exports =");
  const m = { exports: {} };
  new Function("module", "exports", src)(m, m.exports);
  return m.exports;
}
function keys(o, prefix = "") {
  return Object.keys(o).sort().flatMap((k) => {
    const v = o[k];
    const key = prefix ? prefix + "." + k : k;
    return v && typeof v === "object" ? keys(v, key) : [key];
  });
}

const pairs = [
  ["src/i18n/lang/zh-CN/news.js", "src/i18n/lang/en-US/news.js"],
  ["src/i18n/lang/zh-CN/placeholder.js", "src/i18n/lang/en-US/placeholder.js"],
];
for (const [zh, en] of pairs) {
  const a = keys(loadMod(path.resolve(zh)));
  const b = keys(loadMod(path.resolve(en)));
  const same = JSON.stringify(a) === JSON.stringify(b);
  console.log((same ? "OK   " : "DIFF ") + zh + "  ->  " + a.join(", "));
  if (!same) { console.log("  zh:", a); console.log("  en:", b); }
}

for (const f of ["src/views/news/News.vue", "src/views/news/Detail.vue", "src/views/placeholder/Placeholder.vue"]) {
  const sfc = compiler.parseComponent(fs.readFileSync(path.resolve(f), "utf8"));
  const res = compiler.compile(sfc.template.content);
  console.log((res.errors.length ? "TEMPLATE ERRORS " + f + ": " + res.errors.join("; ") : "TEMPLATE OK " + f));
}
