{"command": "@'
const fs = require("fs");
const path = require("path");

function loadDir(dir) {
  const out = {};
  for (const f of fs.readdirSync(dir)) {
    if (!f.endsWith(".js")) continue;
    const src = fs.readFileSync(path.join(dir, f), "utf8").replace(/export default/, "module.exports =");
    const m = { exports: {} };
    new Function("module", "exports", src)(m, m.exports);
    out[f.replace(/\.js$/, "")] = m.exports;
  }
  return out;
}
const zh = loadDir("src/i18n/lang/zh-CN");
const en = loadDir("src/i18n/lang/en-US");
const lookup = (tree, key) => key.split(".").reduce((o, k) => (o == null ? o : o[k]), tree);

const files = ["src/views/news/News.vue", "src/views/news/Detail.vue", "src/views/placeholder/Placeholder.vue"];
const used = new Set();
for (const f of files) {
  const src = fs.readFileSync(f, "utf8");
  for (const m of src.matchAll(/\$t\(\s*['"]([^'"]+)['"]/g)) used.add(m[1]);
}
console.log("keys used in my views:", [...used].join(", "));
let bad = 0;
for (const k of used) {
  const z = lookup(zh, k), e = lookup(en, k);
  if (z === undefined || e === undefined) { bad++; console.log("MISSING", k, "zh=", z, "en=", e); }
  else console.log("OK  " + k.padEnd(22) + " zh=" + JSON.stringify(z).padEnd(28) + " en=" + JSON.stringify(e));
}
console.log(bad ? "FAILED" : "ALL KEYS PRESENT IN BOTH LOCALES");
